import urllib.request
import urllib.error
import time

class APIError(Exception):
    """Base exception for APIClient"""
    pass

class RateLimitError(APIError):
    """Raised when HTTP 429 persists after retries"""
    pass

class ServerError(APIError):
    """Raised when HTTP 5xx persists after retries"""
    pass

class ClientError(APIError):
    """Raised when HTTP 4xx (other than 429) occurs"""
    pass

class ConnectionError(APIError):
    """Raised when network errors persist after retries"""
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}/{path.lstrip('/')}"

        # Retry configurations
        # Rate limit: 3 retries, backoff [0.5, 1, 2]
        # Server error: 1 retry, backoff [1]
        # Network error: 1 retry, backoff [1]

        rate_limit_retries = 3
        rate_limit_backoff = [0.5, 1.0, 2.0]

        server_error_retries = 1
        server_error_backoff = [1.0]

        network_error_retries = 1
        network_error_backoff = [1.0]

        # Track attempts for different error types
        rl_attempt = 0
        se_attempt = 0
        ne_attempt = 0

        while True:
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')

            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if rl_attempt < rate_limit_retries:
                        time.sleep(rate_limit_backoff[rl_attempt])
                        rl_attempt += 1
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after {rl_attempt} retries.")

                elif 500 <= e.code < 600:
                    if se_attempt < server_error_retries:
                        time.sleep(server_error_backoff[se_attempt])
                        se_attempt += 1
                        continue
                    else:
                        raise ServerError(f"Server error {e.code} after {se_attempt} retries.")

                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error: {e.code} {e.reason}")

                else:
                    raise APIError(f"Unexpected HTTP error: {e.code}")

            except urllib.error.URLError as e:
                if ne_attempt < network_error_retries:
                    time.sleep(network_error_backoff[ne_attempt])
                    ne_attempt += 1
                    continue
                else:
                    raise ConnectionError(f"Network error: {e.reason}")
